const CACHE='milai-accounts-v10',FILES=["./", "assets/inventory-scan.webp", "core.mjs", "account-access.mjs", "license-quota.mjs", "icon-192.png", "style.css", "external-backup.mjs", "inventory-storage.mjs", "manifest.json", "firebase-config.mjs", "accounts.mjs", "index.html", "app.js", "icon.svg", "icon-512.png", "xlsx-rtl.mjs", "israel-time.mjs", "catalog.json", "vendor/xlsx.min.js", "vendor/firebase-sdk.mjs", "vendor/zxing.min.js"];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith('milai-')&&k!==CACHE)await caches.delete(k);await self.clients.claim()})()));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin||new URL(e.request.url).pathname.startsWith('/manage/'))return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||Response.error())))})